// Run this same harness beside each exact app assembly, in isolated folders.
using System;using System.IO;using System.Linq;using System.Reflection;using System.Diagnostics;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;using V15Voice;
public static class PerformanceBenchmark {
 static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}
 [STAThread]public static void Main(string[] args){string version=typeof(MainForm).Assembly.GetName().Version.ToString();if(args.Length>0&&args[0]=="cache"){string root=Path.Combine(Path.GetTempPath(),"archive-bench "+Guid.NewGuid().ToString("N")),folder=Path.Combine(root,"text_audio");Directory.CreateDirectory(folder);for(int i=0;i<2000;i++)File.WriteAllText(Path.Combine(folder,i+".wav"),"metadata fixture");var c=Stopwatch.StartNew();for(int i=0;i<60;i++)new SpeechArchive(root);c.Stop();Console.WriteLine("BENCH_CACHE|"+version+"|"+c.Elapsed.TotalMilliseconds.ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+"|60|2000");Directory.Delete(root,true);return;}
  Application.EnableVisualStyles();var form=new MainForm();form.Shown+=(s,e)=>{try{string root=Path.Combine(Path.GetTempPath(),"ui-bench "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var paths=new List<string>();for(int i=0;i<80;i++){string p=Path.Combine(root,"story"+i+".srt");File.WriteAllText(p,"1\n00:00:00,000 --> 00:00:03,200\nThis is a short benchmark sentence.\n");paths.Add(p);}Call(form,"AddFiles",(object)paths.ToArray());var jobs=(List<BatchJob>)F(form,"jobs");jobs[0].State=JobState.Running;jobs[0].Progress.Begin();var rows=((DataGridView)F(form,"jobGrid")).Rows;var initial=rows[0];int rebuilt=0;bool fast=form.GetType().GetMethod("PublishRenderUi",BindingFlags.NonPublic|BindingFlags.Instance)!=null;var clock=Stopwatch.StartNew();for(int i=0;i<200;i++){jobs[0].Progress.Update(i%99,"event "+i);if(fast)Call(form,"PublishRenderUi",i%99,"event "+i);else{Call(form,"RefreshJobs");if(!Object.ReferenceEquals(initial,rows[0]))rebuilt++;}}if(fast)Call(form,"FlushRenderUi");clock.Stop();Console.WriteLine("BENCH_UI|"+version+"|"+clock.Elapsed.TotalMilliseconds.ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+"|200|80|"+rebuilt);jobs[0].Progress.Finish(false);jobs[0].State=JobState.Queued;}
  catch(Exception ex){Console.WriteLine(ex);Environment.ExitCode=1;}finally{form.Close();}};Application.Run(form);
 }
}
